extern alias apiv6;
using System.Security.Cryptography;using System.Text;using Npgsql;using SanSo.Api.Modules;using SanSo.Api.Security;using Xunit;using Store=apiv6::SanSo.Api.V6.PostgresOnboardingStoreV1;
namespace SanSo.Api.V6.Tests;
public sealed class PostgresOnboardingPersistenceV1Tests
{
 [Fact]public async Task SevenStepsPersistEncryptedFieldsAndRejectOutOfOrderMutation(){var cs=Environment.GetEnvironmentVariable("SANSO_RUNTIME_POSTGRES");if(string.IsNullOrWhiteSpace(cs))return;var tenant=Guid.NewGuid();var actor=Guid.NewGuid();var reconciliation=Guid.NewGuid();await Seed(cs,tenant,actor,reconciliation);await using var source=NpgsqlDataSource.Create(cs);var protector=new TenantFieldProtector(SHA256.HashData(Encoding.UTF8.GetBytes("onboarding-integration-test-key")),"test-v1");var store=new Store(source,protector);Assert.Equal(1,(await store.Start(tenant.ToString(),default)).CurrentStep);var profile=new BusinessProfileDraft(BusinessSubjectType.Company,"Công ty Demo","0123456789","123 Đường Kiểm Thử");var step2=await store.SaveBusinessProfile(tenant.ToString(),profile,default);Assert.Equal("******6789",step2.TaxIdentifierMasked);Assert.Equal("123 Đường Kiểm Thử",step2.Address);await Assert.ThrowsAsync<OnboardingValidationException>(()=>store.SaveBusinessProfile(tenant.ToString(),profile,default));await store.SelectSource(tenant.ToString(),SourceMode.Csv,default);await store.SelectBackfill(tenant.ToString(),DateOnly.FromDateTime(DateTime.UtcNow.AddDays(-30)),default);await store.ConfirmSku(tenant.ToString(),1,default);await store.OpeningBalances(tenant.ToString(),[new("SKU-ONBOARD",2,15000)],default);await store.Disclaimer(tenant.ToString(),"pilot-v1",actor.ToString(),true,default);var done=await store.Complete(tenant.ToString(),reconciliation.ToString(),true,default);Assert.Equal(8,done.CurrentStep);await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT tax_identifier_protected,tax_identifier_last4,address_protected,field_key_version,current_step FROM onboarding_profiles WHERE organization_id=$1";q.Parameters.AddWithValue(tenant);await using var r=await q.ExecuteReaderAsync();Assert.True(await r.ReadAsync());var taxCipher=r.GetString(0);var addressCipher=r.GetString(2);Assert.DoesNotContain("0123456789",taxCipher);Assert.DoesNotContain("123 Đường",addressCipher);Assert.Equal("6789",r.GetString(1));Assert.Equal("test-v1",r.GetString(3));Assert.Equal(8,r.GetInt32(4));Assert.Throws<CryptographicException>(()=>protector.Unprotect(Guid.NewGuid().ToString(),"tax_identifier",taxCipher));}
 static async Task Seed(string cs,Guid tenant,Guid actor,Guid reconciliation){var settlement=Guid.NewGuid();await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();foreach(var item in new[]{(Sql:"INSERT INTO organizations(id,slug,name)VALUES($1,$2,'Onboarding test')",Args:new object[]{tenant,$"onboarding-{tenant:N}"}),(Sql:"INSERT INTO users(id,email,display_name,password_hash,mfa_enabled)VALUES($1,$2,'Actor','managed',true)",Args:new object[]{actor,$"actor-{actor:N}@example.invalid"}),(Sql:"INSERT INTO settlements(id,organization_id,code,actual_amount,paid_at)VALUES($1,$2,$3,0,now())",Args:new object[]{settlement,tenant,$"SET-{settlement:N}"}),(Sql:"INSERT INTO reconciliation_runs(id,organization_id,settlement_id,status,expected_amount,actual_amount,difference,mapping_version,input_checksum)VALUES($1,$2,$3,'MATCHED',0,0,0,1,'test')",Args:new object[]{reconciliation,tenant,settlement})}){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText=item.Sql;foreach(var value in item.Args)q.Parameters.AddWithValue(value);await q.ExecuteNonQueryAsync();}await tx.CommitAsync();}
}
